"""Golden file comparison used by the settlement desk's visible examples."""
import json
import os
from pathlib import Path
import tempfile


def read(path):
    return json.loads(Path(path).read_text(encoding="utf-8"))


def compare(expected, actual):
    differences = []
    if len(expected) != len(actual):
        differences.append(f"row count: expected {len(expected)}, got {len(actual)}")
    for i, (left, right) in enumerate(zip(expected, actual)):
        if left != right:
            differences.append(f"row {i}: expected {left!r}, got {right!r}")
    return differences


def record(path, rows):
    path = Path(path)
    with tempfile.NamedTemporaryFile(mode="w", dir=path.parent, encoding="utf-8",
                                     delete=False) as stream:
        temp = Path(stream.name)
        json.dump(rows, stream, indent=2)
        stream.write("\n")
    try:
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)


def inspect_candidate(path, rows):
    return compare(read(path), rows)


def receipt_for(path):
    """Find the reconciliation receipt belonging to this approval table.

    Receipt paths are relative to the receipt, not the working directory.
    Unrelated/custom golden files retain positional comparison semantics.
    """
    path = Path(path)
    receipt_path = path.parent / "receipt.json"
    if not receipt_path.exists():
        return None
    receipt = read(receipt_path)
    table = receipt_path.parent / receipt["table"]
    if table.resolve() != path.resolve():
        return None
    return {key: receipt_path.parent / receipt[key]
            for key in ("table", "case_order", "calendar_edition")}


def reconcile(rows, values, case_order):
    """Put live input-order values into approval order by stable case identity."""
    if len(rows) != len(values):
        raise ValueError(f"row count: expected {len(rows)}, got {len(values)}")
    cases = [row["case"] for row in rows]
    if any(not isinstance(case, str) or not case for case in cases):
        raise ValueError("input cases must be nonempty strings")
    if len(set(cases)) != len(cases):
        raise ValueError("duplicate input case")
    if not isinstance(case_order, list) or any(
            not isinstance(case, str) or not case for case in case_order):
        raise ValueError("approval case order must be a list of nonempty strings")
    if len(set(case_order)) != len(case_order):
        raise ValueError("duplicate approval case")
    if set(cases) != set(case_order):
        raise ValueError("input cases do not match approval case order")
    by_case = dict(zip(cases, values))
    return [by_case[case] for case in case_order]
